import{_ as o,o as d,c as t,a6 as a}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"模型、效率与权限","description":"模型切换、推理强度、执行速度、权限模式与规则管理","frontmatter":{"title":"模型、效率与权限","description":"模型切换、推理强度、执行速度、权限模式与规则管理","source":"https://daiw.org/manual/claude-code/commands-model-permissions"},"headers":[],"relativePath":"manual/agent/claude-code/commands-model-permissions.md","filePath":"manual/agent/claude-code/commands-model-permissions.md"}'),c={name:"manual/agent/claude-code/commands-model-permissions.md"};function s(n,e,r,l,i,p){return d(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="模型、效率与权限" tabindex="-1">模型、效率与权限 <a class="header-anchor" href="#模型、效率与权限" aria-label="Permalink to &quot;模型、效率与权限&quot;">​</a></h1><blockquote><p>模型切换、推理强度、执行速度、权限模式与规则管理</p></blockquote><h2 id="模型与推理" tabindex="-1">模型与推理 <a class="header-anchor" href="#模型与推理" aria-label="Permalink to &quot;模型与推理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/model [model]</code></td><td>切换模型并保存为新会话默认值；支持左右方向键调整推理强度。不带参数打开选择器，在某一行按 <code>s</code> 表示“仅本次会话切换”。⚠️ v2.1.277 起 Anthropic API 上 Fable 始终出现在选择器里，只有组织设置禁用它时才显示为灰色。⚠️ v2.1.280 起 <code>opus</code> 指向新的默认 Opus 模型 Opus 5.5，Pro 与 Team Standard 套餐的默认模型也从 Sonnet 改为 Opus；v2.1.284 起 Anthropic API 上的 <code>sonnet</code> 默认指向 Sonnet 5.5；v2.1.293 起 Anthropic API 上的 <code>haiku</code> 默认指向 Haiku 5.5；v2.1.311 起在 <code>[1m]</code> 后缀无实际作用的模型上自动去掉该后缀与标签（传入仍兼容）</td></tr><tr><td><code>/effort [level|auto]</code></td><td>设置推理强度：<code>low</code>/<code>medium</code>/<code>high</code>/<code>xhigh</code>/<code>max</code>（可用档位取决于模型）。不带参数打开滑块交互。Ultracode 现在是独立开关：在滑块按 <code>Tab</code> 切换，或输入 <code>/effort ultracode [on|off]</code>；它不再强制使用 <code>xhigh</code>。⚠️ v2.1.251 起按模型分别保存默认强度；v2.1.257 起在滑块里按 <code>s</code> 只改本会话。⚠️ v2.1.280 起按模型保存之前存下的强度不再套到 Opus 5.5 这类新模型上（它们从自己的默认强度起步，Opus 5.5 默认 <code>medium</code>）；⚠️ v2.1.311 起交互终端里的 <code>ultrathink</code> 关键词在 Opus 5.5、Sonnet 5.5、Haiku 5.5 与 Fable 5.1（Anthropic API）上把该轮推理强度提至 <code>xhigh</code>（设 <code>CLAUDE_CODE_DISABLE_ULTRATHINK=1</code> 关闭）</td></tr><tr><td><code>/fast [on|off]</code></td><td>切换 fast mode（用更高单价换取更快响应速度）。⚠️ v2.1.219 起适用于 <strong>Opus 5 与 Opus 4.8</strong>，Opus 4.7 已退出 fast mode；v2.1.304 起 Opus 5.5 的 <code>/fast</code> 对话框去掉「(research preview)」字样；⚠️ <strong>v2.1.316 起 Opus 4.8 的 fast mode 弃用</strong>（2026-10-30 起弃用，2026-11-30 移除，移除后直接报错且不回退标准速度，建议迁至 Opus 5.5）。🆕 v2.1.271 起 Claude Code Remote 会话（云端与自托管运行环境）也支持：宿主的 fast mode 设置或在会话里敲的 <code>/fast</code>，在组织允许时生效</td></tr><tr><td><code>/advisor [model|off]</code></td><td>启用/关闭顾问工具：在任务关键节点额外咨询第二个模型的意见，支持 <code>opus</code>/<code>sonnet</code>/<code>fable</code> 或完整模型 ID（v2.1.98+）。v2.1.260 起桌面端、Remote Control 与无头会话也能用文本形式 <code>/advisor &lt;model&gt;</code>、<code>/advisor off</code>；🆕 v2.1.300 起 Claude Platform on AWS 也支持（设 <code>CLAUDE_CODE_DISABLE_ADVISOR_TOOL=1</code> 可关闭顾问工具）</td></tr></tbody></table><h2 id="权限与执行模式" tabindex="-1">权限与执行模式 <a class="header-anchor" href="#权限与执行模式" aria-label="Permalink to &quot;权限与执行模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/permissions</code></td><td>管理 allow/ask/deny 规则的交互界面，可按作用域查看、增删规则、管理工作目录、查看 auto mode 最近的拒绝记录。别名 <code>/allowed-tools</code>。v2.1.246 起新增 <strong>Auto mode 标签页</strong>，可查看与编辑 auto mode 分类器规则；v2.1.234 起 Claude 工作时也能打开，改动作用于当前这一轮剩余部分；v2.1.280 起删除规则与移除目录的确认默认选 No；🆕 v2.1.314 起审查标签页改名为 <strong>Recently blocked</strong>，且在终端过矮无法完整显示命令时拒绝批准；v2.1.318 起规则详情、内置规则与删除确认统一使用标准对话框（连按两次 Ctrl+C 返回或取消，不再退出 CLI）</td></tr><tr><td><code>/auto-mode-setup</code></td><td>🆕 <strong>v2.1.304+</strong>：引导式配置向导，读取当前项目与近期会话，教 auto mode 了解你的环境（Bedrock、Vertex、Foundry、Claude apps 网关与关闭遥测的会话均可用）</td></tr><tr><td><code>/plan [description]</code></td><td>直接进入计划模式（Claude 只读文件、给出方案，不做任何修改，需你确认后才真正动手）；可带任务描述，如 <code>/plan 修复认证 bug</code></td></tr><tr><td><code>/sandbox</code></td><td>切换沙箱模式（仅部分平台支持）</td></tr></tbody></table><h2 id="会话级配置" tabindex="-1">会话级配置 <a class="header-anchor" href="#会话级配置" aria-label="Permalink to &quot;会话级配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/config [key=value ...]</code></td><td>打开设置界面调整主题、模型、输出风格等；也可以直接 <code>/config thinking=false</code>、<code>/config model=sonnet</code> 一步到位设置，非交互模式（<code>-p</code>）和 Remote Control 也支持这种写法。别名 <code>/settings</code>。🆕 v2.1.271 起全屏模式下支持鼠标（滚轮滚动设置列表、点击设置的值即可修改）；v2.1.277 起多了「Project instructions」一项，用来修改“没有 <code>CLAUDE.md</code> 时改读 <code>AGENTS.md</code>”这项行为；v2.1.302 起新增「Idle compaction」开关行</td></tr><tr><td><code>/goal [condition|clear]</code></td><td>设定一个目标条件，Claude 会持续跨轮工作直到条件满足；不带参数查看当前/最近达成的目标，传 <code>clear</code>/<code>stop</code>/<code>off</code> 提前取消。v2.1.234 起被后台任务卡住 30 分钟以上会主动检查进度（之后退避，<code>CLAUDE_CODE_GOAL_CHECKIN_MINUTES=0</code> 关闭）；v2.1.269 起遇到 API 错误或断网会退避重试，或暂停并说明原因，而不是静默停滞</td></tr></tbody></table><h2 id="权限模式说明" tabindex="-1">权限模式说明 <a class="header-anchor" href="#权限模式说明" aria-label="Permalink to &quot;权限模式说明&quot;">​</a></h2><p>Claude Code 有一组可以互相切换的权限模式（用 <code>--permission-mode</code> 启动指定，或会话中按 <code>Shift+Tab</code> 循环切换）：</p><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td><code>default</code>（即 <code>manual</code>）</td><td>每个有副作用的工具调用都需要你手动确认</td></tr><tr><td><code>acceptEdits</code></td><td>自动接受文件编辑，其它操作仍需确认</td></tr><tr><td><code>plan</code></td><td>只读：Claude 探索代码并给出计划，不执行任何修改</td></tr><tr><td><code>auto</code></td><td>用内置分类器自动放行“看起来安全”的操作。⚠️ v2.1.271 起技能与斜杠命令里内联的 <code>!</code> shell 命令改按默认模式的权限规则处理、不再交给分类器；v2.1.273 起 Bedrock、Vertex、Foundry 上暂时默认使用本地分类器（<code>CLAUDE_CODE_AUTO_MODE_SERVER=1</code> 改用平台的服务端分类器）；⚠️ v2.1.278 起 Claude API、Enterprise 以及 Bedrock、Vertex、Foundry 与网关上又改为默认服务端分类器（分类器开销不再收费，<code>CLAUDE_CODE_AUTO_MODE_SERVER=0</code> 退出），<code>/status</code> 的「Auto mode server」一行显示本会话是否在用；v2.1.281 起服务端审查的会话里，只读与沙箱化的 shell 命令也要等审查结果。⚠️ <strong>v2.1.283 起没配置权限模式时，终端与 VS Code 里的交互式会话在所有套餐与提供方上都以 auto mode 起步</strong>（此前只有 Pro、Max、Team 套餐如此），<code>permissions.defaultMode</code> 可覆盖</td></tr><tr><td><code>dontAsk</code></td><td>减少确认提示的更宽松模式</td></tr><tr><td><code>bypassPermissions</code></td><td>跳过全部权限确认（高风险，建议只在隔离/一次性环境使用）。⚠️ v2.1.281 起这个模式与 auto mode 下，危险 <code>rm</code> 的确认最多等 2 分钟，无人回答就拒绝并附上改写提示（<code>CLAUDE_CODE_DISABLE_DANGEROUS_RM_TIMEOUT=1</code> 关闭）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>bypassPermissions</code>（对应 <code>--dangerously-skip-permissions</code>）会跳过几乎所有确认步骤。在生产代码库或有写权限的 CI 环境中使用前，务必先了解清楚它<em>不会</em>跳过什么（见官方 permission modes 文档），并优先考虑限定作用域的 <code>--allowedTools</code> 规则。</p></div><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/model sonnet          # 切到 sonnet 系列</span></span>
<span class="line"><span>/effort high            # 提高本次任务的推理强度</span></span>
<span class="line"><span>/plan 重构订单模块的状态机</span></span>
<span class="line"><span>/permissions            # 打开权限规则管理</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,14)])])}const h=o(c,[["render",s]]);export{u as __pageData,h as default};
